          "revision": 1,
          "status": "Awaiting approval",
          "title": "Recording credit approval evidence",
          "summary": "Connect the decision, supporting documents and operational record so a reviewer can follow the evidence.",
          "sections": [
            {
              "id": "identify",
              "title": "Identify the decision record",
              "paragraphs": [
                "Start from the current case record and identify the approval evidence to which the procedure applies."
              ],
              "bullets": [
                "Confirm the case and facility identifiers.",
                "Identify the source decision and any linked amendments."
              ]
            },
            {
              "id": "link",
              "title": "Link the evidence",
              "paragraphs": [
                "Store references that allow another colleague to find the decision and its supporting material without relying on personal folders."
              ],
              "bullets": [
                "Record document titles, versions and source locations.",
                "Separate the recorded decision from notes and unresolved questions."
              ]
            },
            {
              "id": "verify",
              "title": "Verify the record",
              "paragraphs": [
                "Ask the receiving reviewer to confirm that the links and identifiers describe the same case."
              ],
              "bullets": [
                "Resolve missing or inconsistent references.",
                "Record the verification outcome and any follow-up owner."
              ]
            }
          ],
          "createdAt": "2026-10-11T09:00:00Z",
          "createdBy": "alex",
          "changeSummary": "Initial sample version for document-control demonstration.",
