      "id": "regional-manual-navigation",
      "reference": "WCS-KS-015",
      "area": "regional-operating-manuals",
      "type": "Knowledge sharing",
      "ownerId": "alex",
      "authorId": "alex",
      "reviewerId": "jordan",
